<?php
namespace App\Services; use App\Core\Database;use App\Core\Auth;
final class ProjectService{public function create(array $d):int{$pdo=Database::pdo();$pdo->beginTransaction();try{$status=($d['start_date']??date('Y-m-d'))>date('Y-m-d')?'upcoming':'open';$s=$pdo->prepare('INSERT INTO projects(tenant_id,client_id,business_id,service_id,name,start_date,end_date,status,is_recurring,recurring_cycle_days,cycle_number,created_by,updated_by,created_at,updated_at) VALUES(1,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$s->execute([$d['client_id'],$d['business_id']?:null,$d['service_id']?:null,$d['name'],$d['start_date'],$d['end_date'],$status,!empty($d['is_recurring'])?1:0,$d['recurring_cycle_days']?:null,1,Auth::id(),Auth::id()]);$id=(int)$pdo->lastInsertId();if(!empty($d['is_recurring']))$pdo->prepare('UPDATE projects SET series_id=id WHERE id=?')->execute([$id]);if(!empty($d['service_id'])){try{(new WorkflowEngine)->startForProject($id,(int)$d['service_id']);}catch(\Throwable $e){}}$pdo->commit();(new ActivityService)->record('PROJECT_CREATED','Projects','project',$id);return $id;}catch(\Throwable $e){$pdo->rollBack();throw $e;}}public function update(int $id,array $d):void{$repo=new \App\Repositories\ProjectRepository;$before=$repo->find($id);if(!$before)throw new \RuntimeException('Project not found');Database::pdo()->prepare('UPDATE projects SET name=?,start_date=?,end_date=?,status=?,is_recurring=?,recurring_cycle_days=?,updated_by=?,updated_at=NOW() WHERE id=?')->execute([$d['name'],$d['start_date'],$d['end_date'],$d['status'],$d['is_recurring']??0,$d['recurring_cycle_days']?:null,Auth::id(),$id]);$after=$repo->find($id);(new ActivityService)->record('PROJECT_UPDATED','Projects','project',$id,(new ActivityService)->diff($before,$after),'stage_3');}public function setStatus(int $id,string $status):void{$allowed=['draft','upcoming','open','completed','closed','expired','cancelled','on_hold'];if(!in_array($status,$allowed,true))throw new \InvalidArgumentException('Invalid status');Database::pdo()->prepare('UPDATE projects SET status=?,updated_by=?,updated_at=NOW() WHERE id=?')->execute([$status,Auth::id(),$id]);(new ActivityService)->record('PROJECT_STATUS_CHANGED','Projects','project',$id,['status'=>$status],'stage_3');}}
